from __future__ import annotations

import torch
import torch.nn.functional as F


def _require_same_shape(left: torch.Tensor, right: torch.Tensor) -> None:
    if left.shape != right.shape:
        raise ValueError(f"expected tensors with the same shape, got {tuple(left.shape)} and {tuple(right.shape)}")
    if left.ndim != 2:
        raise ValueError("expected rank-2 tensors with shape [N, D]")


def _negative_cosine(p: torch.Tensor, z: torch.Tensor) -> torch.Tensor:
    _require_same_shape(p, z)
    p = F.normalize(p, dim=-1, eps=1e-8)
    z = F.normalize(z.detach(), dim=-1, eps=1e-8)
    return -(p * z).sum(dim=-1).mean()


def negative_free_loss(p1: torch.Tensor, z2: torch.Tensor, p2: torch.Tensor, z1: torch.Tensor) -> torch.Tensor:
    _require_same_shape(p1, z2)
    _require_same_shape(p2, z1)
    return 0.5 * (_negative_cosine(p1, z2) + _negative_cosine(p2, z1))


def infonce_loss(z1: torch.Tensor, z2: torch.Tensor, temperature: float = 0.5) -> torch.Tensor:
    if temperature <= 0:
        raise ValueError("temperature must be positive")
    _require_same_shape(z1, z2)

    z1 = F.normalize(z1, dim=-1, eps=1e-8)
    z2 = F.normalize(z2, dim=-1, eps=1e-8)
    logits = z1 @ z2.t() / temperature
    labels = torch.arange(z1.size(0), device=z1.device)
    loss_12 = F.cross_entropy(logits, labels)
    loss_21 = F.cross_entropy(logits.t(), labels)
    return 0.5 * (loss_12 + loss_21)


def variance_loss(z: torch.Tensor, target_std: float = 1.0, eps: float = 1e-4) -> torch.Tensor:
    if z.ndim != 2:
        raise ValueError("expected rank-2 tensor with shape [N, D]")
    if target_std <= 0:
        raise ValueError("target_std must be positive")
    std = torch.sqrt(z.var(dim=0, unbiased=False) + eps)
    return F.relu(target_std - std).mean()

from __future__ import annotations

import torch
from torch import nn
import torch.nn.functional as F
from torch_geometric.nn import GCNConv


class GCNEncoder(nn.Module):
    def __init__(self, in_dim: int, hidden_dim: int, use_bn: bool = False) -> None:
        super().__init__()
        self.conv1 = GCNConv(in_dim, hidden_dim)
        self.conv2 = GCNConv(hidden_dim, hidden_dim)
        self.bn1 = nn.BatchNorm1d(hidden_dim) if use_bn else nn.Identity()
        self.bn2 = nn.BatchNorm1d(hidden_dim) if use_bn else nn.Identity()

    def forward(self, x: torch.Tensor, edge_index: torch.Tensor) -> torch.Tensor:
        h = F.relu(self.bn1(self.conv1(x, edge_index)))
        return self.bn2(self.conv2(h, edge_index))


class MLP(nn.Module):
    def __init__(self, in_dim: int, hidden_dim: int, out_dim: int, use_bn: bool = False) -> None:
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(in_dim, hidden_dim),
            nn.BatchNorm1d(hidden_dim) if use_bn else nn.Identity(),
            nn.PReLU(),
            nn.Linear(hidden_dim, out_dim),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.net(x)


class StageBModel(nn.Module):
    def __init__(self, in_dim: int, hidden_dim: int, proj_dim: int, variant: str = "negfree_plain") -> None:
        super().__init__()
        use_bn = variant == "negfree_bn"
        self.encoder = GCNEncoder(in_dim, hidden_dim, use_bn=use_bn)
        self.projector = MLP(hidden_dim, hidden_dim, proj_dim, use_bn=use_bn)
        self.predictor = MLP(proj_dim, hidden_dim, proj_dim)

    def forward(self, x: torch.Tensor, edge_index: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        h = self.encoder(x, edge_index)
        z = self.projector(h)
        p = self.predictor(z)
        return h, z, p

